import{_ as e,o as a,c as s,a2 as n}from"./chunks/framework.CvydjLy7.js";const g=JSON.parse('{"title":"10.11 可观测性与追踪","description":"","frontmatter":{"title":"10.11 可观测性与追踪"},"headers":[{"level":3,"title":"自动插桩","slug":"自动插桩","link":"#自动插桩","children":[]},{"level":3,"title":"一个已经废弃的追踪开关","slug":"一个已经废弃的追踪开关","link":"#一个已经废弃的追踪开关","children":[]},{"level":3,"title":"追踪的依赖","slug":"追踪的依赖","link":"#追踪的依赖","children":[]}],"relativePath":"ch10/11.md","filePath":"ch10/11.md","lastUpdated":1789497795000}'),i={name:"ch10/11.md"};function r(d,t,o,l,c,p){return a(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="_10-11-可观测性与追踪" tabindex="-1">10.11 可观测性与追踪 <a class="header-anchor" href="#_10-11-可观测性与追踪" aria-label="Permalink to &quot;10.11 可观测性与追踪&quot;">​</a></h1><p>前面讲的是离散的三件事：健康、指标、日志。Spring Boot 还提供了一层把“一次调用中发生了什么”串起来的东西 —— Observation。</p><h3 id="自动插桩" tabindex="-1">自动插桩 <a class="header-anchor" href="#自动插桩" aria-label="Permalink to &quot;自动插桩&quot;">​</a></h3><p>引入 <code>starter-actuator</code> 之后，这些位置已经被自动加上了观测点，不需要写代码：</p><table tabindex="0"><thead><tr><th>位置</th><th>观测名</th></tr></thead><tbody><tr><td>服务端 HTTP 请求</td><td><code>http.server.requests</code></td></tr><tr><td>客户端 HTTP 调用</td><td><code>http.client.requests</code></td></tr><tr><td>数据访问</td><td><code>spring.data.repository.invocations</code> 等</td></tr><tr><td>消息消费（第 8 篇那套）</td><td><code>spring.integration</code> 系列</td></tr></tbody></table><p>每条观测同时产出<strong>指标</strong>与<strong>追踪 span</strong>（如果配了追踪）。相关的属性实测有这些：</p><table tabindex="0"><thead><tr><th>属性</th><th>默认值</th><th>作用</th></tr></thead><tbody><tr><td><code>management.observations.http.server.requests.name</code></td><td><code>http.server.requests</code></td><td>服务端观测名</td></tr><tr><td><code>management.observations.http.client.requests.name</code></td><td><code>http.client.requests</code></td><td>客户端观测名</td></tr><tr><td><code>management.observations.key-values.*</code></td><td>无</td><td>加到每条观测上的公共键值</td></tr><tr><td><code>management.observations.enable.&lt;name&gt;</code></td><td>无</td><td>按名字开关某类观测，最长匹配优先</td></tr><tr><td><code>management.observations.annotations.enabled</code></td><td><code>false</code></td><td>是否启用 <code>@Observed</code> / <code>@Timed</code> 这类注解</td></tr></tbody></table><p>最后一条要特别注意：<strong>注解式观测默认是关的</strong>。写了 <code>@Observed</code> 却没生效，先看这个开关，不要怀疑注解写错了。</p><h3 id="一个已经废弃的追踪开关" tabindex="-1">一个已经废弃的追踪开关 <a class="header-anchor" href="#一个已经废弃的追踪开关" aria-label="Permalink to &quot;一个已经废弃的追踪开关&quot;">​</a></h3><p><code>management.tracing.enabled</code> 在 4.x 里已经废弃，而且<strong>废弃级别是 <code>error</code></strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>management.tracing.enabled  →  deprecated, level=error,</span></span>
<span class="line"><span>   replacement = management.tracing.export.enabled, since 4.0.0</span></span></code></pre></div><p><code>level=error</code> 的含义是：<strong>继续用它会导致启动失败</strong>，不是“能用但会打警告”。所以 3.x 升上来的配置必须改这一行：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">management</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  tracing</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 4.x 里 management.tracing.enabled 已废弃且为 error 级，启动直接失败</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    sampling</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # 采样比例，0.0 到 1.0。生产环境别用 1.0</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      probability</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.1</span></span></code></pre></div><h3 id="追踪的依赖" tabindex="-1">追踪的依赖 <a class="header-anchor" href="#追踪的依赖" aria-label="Permalink to &quot;追踪的依赖&quot;">​</a></h3><p>Boot 4 把追踪桥接做成了自己的模块。实测 4.1.1 里可用的是：</p><table tabindex="0"><thead><tr><th>坐标</th><th>说明</th></tr></thead><tbody><tr><td><code>spring-boot-micrometer-tracing</code></td><td>追踪自动配置的公共部分</td></tr><tr><td><code>spring-boot-micrometer-tracing-opentelemetry</code></td><td>接 OpenTelemetry 的桥接与 OTLP/Zipkin 导出</td></tr><tr><td><code>spring-boot-micrometer-tracing-brave</code></td><td>接 Brave 的桥接</td></tr><tr><td><code>spring-boot-micrometer-tracing-test</code></td><td>测试支持</td></tr></tbody></table><p><strong>注意坐标名不是 <code>-bridge-otel</code>。</strong> 3.x 时代大家用的是 Micrometer 侧的 <code>io.micrometer:micrometer-tracing-bridge-otel</code>，Boot 4 里对应的模块叫 <code>spring-boot-micrometer-tracing-opentelemetry</code>（实测 <code>-bridge-otel</code> 与 <code>-bridge-brave</code> 请求都返回 404）。包名也在 <code>micrometer</code> 命名空间下：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>org.springframework.boot.micrometer.tracing.autoconfigure</span></span>
<span class="line"><span>org.springframework.boot.micrometer.tracing.opentelemetry.autoconfigure.otlp</span></span>
<span class="line"><span>org.springframework.boot.micrometer.tracing.opentelemetry.autoconfigure.zipkin</span></span></code></pre></div><p>这一节的内容没有在本机实跑（追踪需要额外的收集端），坐标与属性都是从 4.1.1 的模块与配置元数据里核实出来的。真要接上去，还要自己准备一个 OTLP 接收端。</p><hr>`,20)])])}const m=e(i,[["render",r]]);export{g as __pageData,m as default};
